static void check_usage(const struct device *dev, int expected)
{
	int ret;
	uint32_t usage;

	ret = pm_device_usage_get(dev, &usage);
	zassert_equal(ret, 0, "failed to get device usage");
	zassert_equal(usage, expected, "unexpected usage count");
}

/**
 * @brief Test device runtime PM.
 *
 * This test verifies that the domain is powered on and off when devices
 * are resumed and suspended.
 */
static void test_power_domain_device_runtime(void)
{
	/* All devices are suspended. Domain should be off. */
	zassert_equal(pm_device_state_get(test_domain, NULL), PM_DEVICE_STATE_SUSPENDED,
			"domain should be off");

	/* Resume dev_a. Domain should be on. */
	zassert_ok(pm_device_runtime_get(dev_a));
	zassert_equal(pm_device_state_get(test_domain, NULL), PM_DEVICE_STATE_ACTIVE,
			"domain should be on");

	/* Resume dev_b. Domain should be on. */
	zassert_ok(pm_device_runtime_get(dev_b));
	zassert_equal(pm_device_state_get(test_domain, NULL), PM_DEVICE_STATE_ACTIVE,
			"domain should be on");

	/* Suspend dev_a. Domain should be on. */
	zassert_ok(pm_device_runtime_put(dev_a));
	zassert_equal(pm_device_state_get(test_domain, NULL), PM_DEVICE_STATE_ACTIVE,
			"domain should be on");

	/* Suspend dev_b. Domain should be off. */
	zassert_ok(pm_device_runtime_put(dev_b));
	zassert_equal(pm_device_state_get(test_domain, NULL), PM_DEVICE_STATE_SUSPENDED,
			"domain should be off");
}

ZTEST(power_domain_1cpu, test_power_domain_device_runtime)
{
	test_power_domain_device_runtime();
}

/**
 * @brief Test device runtime PM.
 *
 * This test verifies that the domain is powered on and off when devices
 * are resumed and suspended. It also checks if the usage count is balanced.
 */
static void test_power_domain_device_balanced(void)
{
	/* All devices are suspended. Domain should be off. */
	zassert_equal(pm_device_state_get(test_domain, NULL), PM_DEVICE_STATE_SUSPENDED,
			"domain should be off");
	check_usage(dev_a, 0);

	/* Resume dev_a. Domain should be on. */
	zassert_ok(pm_device_runtime_get(dev_a));
	zassert_equal(pm_device_state_get(test_domain, NULL), PM_DEVICE_STATE_ACTIVE,
			"domain should be on");
	check_usage(dev_a, 1);

	/* Resume dev_a again. Domain should be on. */
	zassert_ok(pm_device_runtime_get(dev_a));
	zassert_equal(pm_device_state_get(test_domain, NULL), PM_DEVICE_STATE_ACTIVE,
			"domain should be on");
	check_usage(dev_a, 2);

	/* Suspend dev_a. Domain should be on. */
	zassert_ok(pm_device_runtime_put(dev_a));
	zassert_equal(pm_device_state_get(test_domain, NULL), PM_DEVICE_STATE_ACTIVE,
			"domain should be on");
	check_usage(dev_a, 1);

	/* Suspend dev_a. Domain should be off. */
	zassert_ok(pm_device_runtime_put(dev_a));
	zassert_equal(pm_device_state_get(test_domain, NULL), PM_DEVICE_STATE_SUSPENDED,
			"domain should be off");
	check_usage(dev_a, 0);

	/* Unbalanced put, should fail */
	zassert_equal(pm_device_runtime_put(dev_a), -EALREADY, "unbalanced put");
	check_usage(dev_a, 0);
}

ZTEST(power_domain_1cpu, test_power_domain_device_balanced)
{
	test_power_domain_device_balanced();
}

/**
 * @brief Test asynchronous device resume.
 *
 * This test verifies that the domain is powered on when devices are resumed
 * asynchronously.
 */
static void test_on_power_domain(void)
{
	/* All devices are suspended. Domain should be off. */
	zassert_equal(pm_device_state_get(test_domain, NULL), PM_DEVICE_STATE_SUSPENDED,
			"domain should be off");

	/* Resume dev_a. Domain should be on. */
	zassert_ok(pm_device_runtime_get(dev_a));
	zassert_equal(pm_device_state_get(test_domain, NULL), PM_DEVICE_STATE_ACTIVE,
			"domain should be on");

	/* Suspend dev_a. Domain should be off. */
	zassert_ok(pm_device_runtime_put(dev_a));
	zassert_equal(pm_device_state_get(test_domain, NULL), PM_DEVICE_STATE_SUSPENDED,
			"domain should be off");
}

ZTEST(power_domain_1cpu, test_on_power_domain)
{
	test_on_power_domain();
}

/**
 * @brief Test adding and removing devices from a power domain.
 *
 * This test verifies that adding and removing devices from a power domain
 * works as expected.
 */
static void test_power_domain_add_remove_duplicate(void)
{
	/* All devices are suspended. Domain should be off. */
	zassert_equal(pm_device_state_get(test_domain, NULL), PM_DEVICE_STATE_SUSPENDED,
			"domain should be off");

	/* Resume dev_a. Domain should be on. */
	zassert_ok(pm_device_runtime_get(dev_a));
	zassert_equal(pm_device_state_get(test_domain, NULL), PM_DEVICE_STATE_ACTIVE,
			"domain should be on");

	/* Remove dev_a from domain. Domain should be off. */
	zassert_ok(pm_device_power_domain_remove(dev_a));
	zassert_equal(pm_device_state_get(test_domain, NULL), PM_DEVICE_STATE_SUSPENDED,
			"domain should be off");

	/* Add dev_a to domain. Domain should be on. */
	zassert_ok(pm_device_power_domain_add(dev_a, test_domain));
	zassert_equal(pm_device_state_get(test_domain, NULL), PM_DEVICE_STATE_ACTIVE,
			"domain should be on");

	/* Add dev_a to domain again. Should fail. */
	zassert_equal(pm_device_power_domain_add(dev_a, test_domain), -EALREADY,
			"device already in domain");

	/* Suspend dev_a. Domain should be off. */
	zassert_ok(pm_device_runtime_put(dev_a));
	zassert_equal(pm_device_state_get(test_domain, NULL), PM_DEVICE_STATE_SUSPENDED,
			"domain should be off");
}

ZTEST(power_domain_1cpu, test_power_domain_add_remove_duplicate)
{
	test_power_domain_add_remove_duplicate();
}

ZTEST_SUITE(power_domain_1cpu, NULL, NULL, NULL, NULL, NULL);
